package ai.eva.android.probe;
import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.nio.charset.StandardCharsets;

/** Authenticated loopback CONNECT tunnel. Android resolves hosts; TLS stays end-to-end. */
final class KernelNetwork {
 final ServerSocket listener;final String credential;final ExecutorService threads=Executors.newCachedThreadPool();final Semaphore capacity=new Semaphore(16);
 KernelNetwork()throws Exception{byte[] secret=new byte[32];new java.security.SecureRandom().nextBytes(secret);String token=android.util.Base64.encodeToString(secret,android.util.Base64.NO_WRAP|android.util.Base64.URL_SAFE);credential=android.util.Base64.encodeToString(("eva:"+token).getBytes(StandardCharsets.UTF_8),android.util.Base64.NO_WRAP);listener=new ServerSocket();listener.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0));proxyUrl="http://eva:"+token+"@127.0.0.1:"+listener.getLocalPort();threads.execute(()->{while(!listener.isClosed())try{Socket socket=listener.accept();if(!capacity.tryAcquire()){socket.close();continue;}threads.execute(()->serve(socket));}catch(IOException ignored){}});}
 final String proxyUrl;
 static void close(Socket s){try{if(s!=null)s.close();}catch(IOException ignored){}}
 void serve(Socket client){Socket remote=null;try{client.setSoTimeout(15000);InputStream input=client.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int matched=0;while(header.size()<8192){int b=input.read();if(b<0)throw new IOException();header.write(b);matched=b==(new int[]{13,10,13,10})[matched]?matched+1:(b==13?1:0);if(matched==4)break;}if(matched!=4)throw new IOException();String[] lines=header.toString("US-ASCII").split("\r\n");boolean authorized=false;for(String line:lines){int at=line.indexOf(':');if(at>0&&line.substring(0,at).equalsIgnoreCase("Proxy-Authorization"))authorized=java.security.MessageDigest.isEqual(line.substring(at+1).trim().getBytes(StandardCharsets.US_ASCII),("Basic "+credential).getBytes(StandardCharsets.US_ASCII));}if(!authorized){client.getOutputStream().write("HTTP/1.1 407 Proxy Authentication Required\r\nProxy-Authenticate: Basic realm=\"Eva\"\r\nContent-Length: 0\r\n\r\n".getBytes(StandardCharsets.US_ASCII));return;}
  String[] request=lines[0].split(" ");if(request.length!=3||!request[0].equals("CONNECT"))throw new IOException();URI target=new URI("https://"+request[1]);String host=target.getHost();int port=target.getPort();if(host==null||target.getUserInfo()!=null||!target.getRawPath().isEmpty()||target.getQuery()!=null||target.getFragment()!=null||port<1||port>65535)throw new IOException();
  remote=new Socket();remote.connect(new InetSocketAddress(host,port),15000);client.getOutputStream().write("HTTP/1.1 200 Connection Established\r\n\r\n".getBytes(StandardCharsets.US_ASCII));client.getOutputStream().flush();client.setSoTimeout(0);final Socket upstream=remote;threads.execute(()->{try{copy(client.getInputStream(),upstream.getOutputStream());}catch(IOException ignored){}finally{close(client);close(upstream);}});copy(remote.getInputStream(),client.getOutputStream());
 }catch(Exception e){try{client.getOutputStream().write("HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n".getBytes(StandardCharsets.US_ASCII));}catch(Exception ignored){}}finally{close(client);close(remote);capacity.release();}}
 static void copy(InputStream in,OutputStream out)throws IOException{byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){out.write(b,0,n);out.flush();}}
}
